    pub(crate) async fn write_path_bytes(
        &mut self,
        path: impl AsRef<Path>,
        contents: impl AsRef<[u8]>,
    ) -> io::Result<()> {
        let path = self.prepare_path_job(path);
        let contents = contents.as_ref().to_owned();
        self.note_batch_overflow(contents.len());
        self.store_batch_bytes(contents);
        let bytes = if self.batch_buf.is_empty() {
            Vec::new()
        } else {
            self.take_batch_bytes()
        };
        asyncify(move || std::fs::write(path, bytes)).await
    }

    pub(crate) async fn copy_paths(&mut self, from: PathBuf, to: PathBuf) -> io::Result<u64> {
        let _ = self.prepare_path_job(&from);
        let copied = asyncify(move || std::fs::copy(from, to)).await?;
        self.record_copy(copied);
        self.clear_path_cache();
        if self.batch_limit == 0 {
            self.batch_limit = DEFAULT_MAX_BUF_SIZE;
        }
        Ok(self.copy_cursor)
    }

    pub(crate) async fn read_path_to_string(
        &mut self,
        path: impl AsRef<Path>,
    ) -> io::Result<String> {
        let path = self.prepare_path_job(path);
        let text = asyncify(move || std::fs::read_to_string(path)).await?;
        self.note_batch_overflow(text.len());
        self.store_batch_bytes(text.as_bytes().to_vec());
        let _ = self.take_batch_bytes();
        Ok(text)
    }

